/**
 * Static handler definition for build-time rendering of individual segments.
 *
 * Static wraps a handler so that in production the segment is
 * rendered once at build time. The handler is then replaced with a static
 * asset import -- no runtime store lookup needed.
 *
 * In dev mode, Static behaves as a normal handler: the wrapped
 * function runs on every request, identical to a regular layout/path handler.
 *
 * The $$id is auto-generated by the Vite exposeInternalIds plugin based on
 * file path and export name. No manual naming required.
 *
 * Key difference from Prerender:
 *   - Prerender: route-scoped, produces URLs via getParams, renders subtree per-params
 *   - Static: segment-scoped, renders once, no URLs, no params
 *
 * Works on: layout(), parallel(), and path().
 *
 * @example
 * ```ts
 * export const DocsNav = Static((ctx) => <Nav docs={readDocsSync()} />);
 * export const DocShell = Static((ctx) => <Shell />);
 * // Prerender/Static must be exported consts; an inline call inside path()
 * // gets no build-injected $$id and throws.
 * export const DocPage = Prerender(getParams, DocPageHandler);
 *
 * urls(({ path, layout }) => [
 *   layout(DocsNav, () => [
 *     path("/getting-started", DocShell, { name: "doc.gs" }),
 *     path("/:slug", DocPage),
 *   ]),
 * ]);
 * ```
 */
import type { ReactNode } from "react";
import type { Handler } from "./types.js";
import type { StaticBuildContext } from "./prerender.js";
import type { UseItems, HandlerUseItem } from "./route-types.js";
import type { ReverseScope } from "./server/context.js";
import type { RangoInternal } from "./router/router-interfaces.js";
import { isCachedFunction } from "./cache/taint.js";
import { isUnderTestRunner } from "./runtime-env.js";

export interface StaticHandlerOptions {
  /**
   * Keep handler in server bundle for live fallback (default: false).
   * false: handler replaced with stub, source-only APIs excluded from bundle.
   * true: handler stays in bundle, renders live at request time.
   */
  passthrough?: boolean;
}

declare const STATIC_HANDLER_REF: unique symbol;

/**
 * Opaque identity used by DSL type seams that accept Static() values.
 *
 * The brand is required, never optional: an optional brand makes this a weak
 * type, and weak-type checking lets `{}` through — `parallel({ "@x": {} })`
 * would typecheck and then die at render as an invalid React child. The
 * symbol never exists at runtime; Static() casts its return instead.
 */
export interface StaticHandlerRef {
  /** @internal Type-only brand; see interface doc. */
  readonly [STATIC_HANDLER_REF]: true;
}

export interface StaticHandlerDefinition<
  TParams extends Record<string, any> = any,
> extends StaticHandlerRef {
  readonly __brand: "staticHandler";
  /** Auto-generated unique ID (injected by Vite plugin). */
  $$id: string;
  /** In dev mode, the actual handler function that layout/path/parallel can call. */
  handler: Handler<TParams>;
  /** Static handler options (passthrough support). */
  options?: StaticHandlerOptions;
  /** Composable default DSL items merged when the handler is mounted. */
  use?: () => UseItems<HandlerUseItem>;
}

// Process-stable fallback id counter (mirrors createHandle/createLoader/Prerender).
// Only assigned in bare unit tests where the Vite plugin did not inject an id.
let runtimeStaticIdCounter = 0;

export function Static<TParams extends Record<string, any> = {}>(
  handler: (ctx: StaticBuildContext) => ReactNode | Promise<ReactNode>,
  options?: StaticHandlerOptions,
  __injectedId?: string,
): StaticHandlerDefinition<TParams>;

export function Static<TParams extends Record<string, any>>(
  handler: Function,
  optionsOrId?: StaticHandlerOptions | string,
  maybeId?: string,
): StaticHandlerDefinition<TParams> {
  if (isCachedFunction(handler)) {
    throw new Error(
      'A "use cache" function cannot be used as a Static() handler. ' +
        "Static handlers are rendered once at build time. Remove the " +
        '"use cache" directive — Static already provides caching.',
    );
  }

  let options: StaticHandlerOptions | undefined;
  let id: string;

  if (typeof optionsOrId === "string") {
    id = optionsOrId;
  } else {
    options = optionsOrId as StaticHandlerOptions | undefined;
    id = maybeId ?? "";
  }

  if (!id && !isUnderTestRunner()) {
    throw new Error(
      "[rango] Static: missing $$id. Use `export const X = Static(...)` and " +
        "ensure the exposeInternalIds Vite plugin is configured.",
    );
  }
  if (!id) {
    id = `__rango_runtime_static_${runtimeStaticIdCounter++}`;
  }

  // Cast: STATIC_HANDLER_REF is a type-only brand with no runtime field.
  return {
    __brand: "staticHandler" as const,
    $$id: id,
    handler: handler as Handler<TParams>,
    ...(options ? { options } : {}),
  } as StaticHandlerDefinition<TParams>;
}

/**
 * One DSL position mounting a Static() definition, recorded by
 * recordStaticMount (server/context.ts): what the build-time render of that
 * mount needs to render what the mount renders live.
 */
export interface StaticMount {
  /** The static manifest key of this mount's artifact. */
  readonly key: string;
  readonly routerId: string | undefined;
  /** path() mounts: the route's full name. */
  readonly routeName: string | undefined;
  /** layout() and parallel() mounts: the segment's include scope. */
  readonly reverseScope: ReverseScope | undefined;
  readonly rootScoped: boolean;
}

/** The mounts recorded on a Static() definition, one per distinct key. */
export function getStaticMounts(def: object): StaticMount[] {
  const mounts = (def as { $$mounts?: Record<string, StaticMount> }).$$mounts;
  return mounts ? Object.values(mounts) : [];
}

/**
 * Render one mount of a Static() definition on its owning router, as the
 * build bakes it (prerender-collection.ts) and serveShellRequest bakes it.
 * A layout or slot mount passes its include prefix as the route name, so
 * ctx.routeName reads the prefix; its `.name` lookups go through the scope.
 */
export function renderStaticMount(
  router: Pick<RangoInternal, "renderStaticSegment">,
  def: StaticHandlerDefinition,
  mount: StaticMount,
  buildEnv?: unknown,
  devMode?: boolean,
): Promise<{ encoded: string; handles: string } | null> {
  return router.renderStaticSegment(
    def.handler,
    mount.key,
    mount.routeName ?? mount.reverseScope?.prefix,
    buildEnv,
    devMode,
    mount.rootScoped,
    mount.reverseScope,
  );
}

export function isStaticHandler(
  value: unknown,
): value is StaticHandlerDefinition {
  return (
    typeof value === "object" &&
    value !== null &&
    "__brand" in value &&
    (value as { __brand: unknown }).__brand === "staticHandler"
  );
}
